// ────────────────────────────── harness ──────────────────────────────

/** Let every pending promise chain settle. */
const settle = async () => {
  await new Promise((resolve) => setImmediate(resolve))
  await new Promise((resolve) => setImmediate(resolve))
}

/**
 * A minimal `ServerResponse` stand-in.
 *
 * @returns {object} response double.
 */
function createRes() {
  return {
    statusCode: 200,
    headers: {},
    body: '',
    headersSent: false,
    setHeader(name, value) {
      this.headers[String(name).toLowerCase()] = value
    },
    end(chunk) {
      this.body += chunk === undefined ? '' : String(chunk)
      this.headersSent = true
    },
    destroy() {},
  }
}

/**
 * A minimal `IncomingMessage` stand-in that emits its body asynchronously.
 *
 * @param {object} [init] - request shape.
 * @returns {object} request double.
 */
function createReq(init = {}) {
  const handlers = { data: [], end: [], error: [] }
  const req = {
    method: init.method ?? 'GET',
    url: init.url ?? '/',
    headers: { host: '127.0.0.1:19387', ...(init.headers ?? {}) },
    on(event, handler) {
      ;(handlers[event] ??= []).push(handler)
      return req
    },
    destroy() {},
  }
  queueMicrotask(() => {
    if (init.body !== undefined) {
      const chunk = Buffer.from(init.body)
      for (const handler of handlers.data) handler(chunk)
    }
    for (const handler of handlers.end) handler()
  })
  return req
}

/**
 * Call the API and parse the response.
 *
 * @param {object} api - `createWebApi` handle.
 * @param {object} [init] - request shape.
 * @returns {Promise<{status: number, headers: object, body: object, raw: string}>}
 * the response.
 */
async function call(api, init = {}) {
  const res = createRes()
  await api.handler(createReq(init), res)
  let body = null
  try {
    body = JSON.parse(res.body)
  } catch {
    body = null
  }
  return { status: res.statusCode, headers: res.headers, body, raw: res.body }
}

/**
 * An in-memory account store matching `createAccountStore`'s shape.
 *
 * @param {object | null} [initial] - starting account.
 * @returns {object} store double with its `state` exposed.
 */
function createMemoryStore(initial = null) {
  const state = { account: initial, saves: [], clears: 0, failSave: false }
  return {
    state,
    load: async () => state.account,
    save: async (account) => {
      if (state.failSave) throw new Error('disk full')
      state.account = account
      state.saves.push(account)
    },
    clear: async () => {
      state.account = null
      state.clears += 1
    },
    readBuf: async () => '',
    writeBuf: async () => {},
    path: 'memory://account.json',
  }
}

/**
 * Build the API under test with fake login endpoints and a fake store.
 *
 * @param {object} [options] - overrides.
 * @returns {{api: object, store: object, calls: object[]}} the handle.
 */
function createApi(options = {}) {
  const store = options.store ?? createMemoryStore()
  const calls = []
  const api = createWebApi({
    config: options.config ?? { baseUrl: 'https://ilinkai.test', dataDir: 'memory://' },
    // Channel-aware: the Feishu routes must get the Feishu service, not whatever
    // the WeChat slot happens to hold.
    getService: (channel) => (channel === 'feishu' ? options.feishuService : options.service),
    getBridgeSettings: options.getBridgeSettings,
    log: () => {},
    deps: {
      now: options.now,
      intervalMs: options.intervalMs,
      storeFactory: () => store,
      beginLogin: async (input) => {
        calls.push({ kind: 'beginLogin', input })
        if (options.beginError) throw options.beginError
        return options.beginResult ?? {
          qrcode: 'qr-1',
          qrUrl: 'https://liteapp.weixin.qq.com/q/abc?qrcode=qr-1&bot_type=3',
          expiresAt: Date.now() + 120000,
          expiresIn: 120,
        }
      },
      pollLogin: async (input) => {
        calls.push({ kind: 'pollLogin', input })
        if (options.pollError) throw options.pollError
        if (typeof options.pollResult === 'function') return options.pollResult(input)
        return options.pollResult ?? { status: 'pending' }
      },
    },
  })
  return { api, store, calls }
}

