test('mountWebApi registers one prefix route, one error listener, and disposes them', () => {
  const routes = []
  const listeners = []
  const effects = []
  const webServer = {
    register(route) {
      routes.push(route)
      return () => {
        const at = routes.indexOf(route)
        if (at !== -1) routes.splice(at, 1)
      }
    },
  }
  const ctx = {
    get: (name) => (name === 'webServer' ? webServer : undefined),
    inject(names, callback) {
      assert.deepEqual(names, ['webServer'])
      callback(ctx)
    },
    on(event, handler) {
      listeners.push([event, handler])
      return () => {}
    },
    effect(fn) {
      effects.push(fn)
      return () => {}
    },
  }

  const dispose = mountWebApi(ctx, { log: () => {} })
  assert.equal(routes.length, 1)
  assert.equal(routes[0].kind, 'prefix')
  assert.equal(routes[0].path, WEB_API_PREFIX)
  assert.equal(typeof routes[0].handler, 'function')
  assert.equal(listeners.length, 1)
  assert.equal(listeners[0][0], 'wechat-ilink/error')
  assert.equal(effects.length, 1)

  dispose()
  assert.equal(routes.length, 0)
})

test('[REGRESSION] the mounted API answers a channel route with that channel service', async () => {
  // The WeChat service mounts this API and hands over itself. A lookup that
  // ignores the channel argument then answers the Feishu routes with the WeChat
  // service — and because both channels happen to have `beginLogin`, it answers
  // with a *plausible* payload (a WeChat QR) instead of an error. The card got a
  // QR url with no device code in it, which is a broken image and nothing else.
  const routes = []
  const webServer = {
    register(route) {
      routes.push(route)
      return () => {}
    },
  }
  const ctx = {
    get: (name) => (name === 'webServer' ? webServer : undefined),
    inject: (_names, callback) => callback(ctx),
    on: () => () => {},
    effect: () => () => {},
  }
  const wechat = {
    channel: 'wechat-ilink',
    getStatus: () => ({ channel: 'wechat-ilink', botId: 'wechat-bot' }),
    beginLogin: async () => ({ qrcode: 'wechat-qr', qrUrl: 'https://liteapp.weixin.qq.com/q/x', expiresAt: Date.now() }),
  }
  const feishu = {
    channel: 'feishu',
    getStatus: () => ({ channel: 'feishu', appId: 'cli_1', connected: false }),
    beginLogin: async () => ({ deviceCode: 'dc-1', qrUrl: 'https://open.feishu.cn/page/launcher', interval: 5000 }),
  }
  setService(wechat)
  setService(feishu)
  const dispose = mountWebApi(ctx, { log: () => {}, service: wechat })

  try {
    const res = createRes()
    await routes[0].handler(
      createReq({ url: `${WEB_API_PREFIX}/feishu/login/begin`, method: 'POST', body: '{}' }),
      res,
    )
    const body = JSON.parse(res.body)
    assert.equal(body.qrcode, 'dc-1', 'the Feishu route must reach the Feishu service')
    assert.match(body.qrImageUrl, /qrcode=dc-1$/)
    assert.ok(!String(body.qrUrl).includes('weixin.qq.com'), 'a WeChat QR is the wrong answer here')

    // And the WeChat routes still get the WeChat service.
    const own = createRes()
    await routes[0].handler(createReq({ url: `${WEB_API_PREFIX}/feishu/status` }), own)
    assert.equal(JSON.parse(own.body).status.channel, 'feishu')
  } finally {
    dispose()
    clearService()
  }
})

test('[REGRESSION] the Feishu row publishes itself and mounts the API on its own', async () => {
  // Two separate failures made the card report "the channel is not loaded" for a
  // perfectly healthy row: the Feishu service never published into the keyed
  // registry, and the web API was mounted only by the WeChat row — so a profile
  // that disables WeChat took the Feishu card's routes with it.
  const { apply: applyFeishu } = await import('wechat-feishu-linker/feishu')
  const routes = []
  const webServer = {
    register(route) {
      routes.push(route)
      return () => {}
    },
  }
  const ctx = {
    get: (name) => (name === 'webServer' ? webServer : undefined),
    inject: (_names, callback) => callback(ctx),
    on: () => () => {},
    effect: () => () => {},
    logger: undefined,
  }
  // No credentials on disk, so `start()` stays unbound and opens no socket.
  const channel = applyFeishu(ctx, { dataDir: 'memory://feishu-none' })
  try {
    assert.equal(getService('feishu'), channel, 'the row must publish itself')
    assert.equal(routes.length, 1, 'and mount the shared API when nobody else has')
    assert.equal(routes[0].path, WEB_API_PREFIX)

    const res = createRes()
    await routes[0].handler(createReq({ url: `${WEB_API_PREFIX}/feishu/status` }), res)
    const body = JSON.parse(res.body)
    assert.equal(body.mounted, true, 'the card must see a mounted row, not a missing one')
    assert.equal(body.status.channel, 'feishu')
  } finally {
    channel.dispose?.()
    clearService()
  }
})

test('mountWebApi degrades when the host has no webServer', () => {  const injected = []
  const ctx = {
    get: () => undefined,
    inject(names, callback) {
      injected.push(names)
      callback(ctx)
    },
  }
  assert.doesNotThrow(() => mountWebApi(ctx, { log: () => {} }))
  assert.deepEqual(injected, [['webServer']])
})

test('mountWebApi falls back to a direct webServer lookup without ctx.inject', () => {
  const routes = []
  const ctx = {
    get: (name) => (name === 'webServer' ? { register: (route) => (routes.push(route), () => {}) } : undefined),
  }
  mountWebApi(ctx, { log: () => {} })
  assert.equal(routes.length, 1)
  assert.equal(routes[0].path, WEB_API_PREFIX)
})

test('mountWebApi mirrors channel poll errors into lastError', async () => {
  let handler
  let listener
  const ctx = {
    get: () => undefined,
    inject: (_names, callback) =>
      callback({
        get: () => ({
          register: (route) => {
            handler = route.handler
            return () => {}
          },
        }),
      }),
    on: (_event, fn) => {
      listener = fn
      return () => {}
    },
  }
  mountWebApi(ctx, { log: () => {} })
  assert.equal(typeof handler, 'function')
  listener({ message: 'poll exploded' })

  const res = createRes()
  await handler(createReq({ url: `${WEB_API_PREFIX}/status` }), res)
  assert.equal(JSON.parse(res.body).lastError, 'poll exploded')
})

