test('GET /status reports a bound account without leaking the token', async () => {
  const service = {
    config: { baseUrl: 'https://ilinkai.test' },
    dataDirectory: 'memory://',
    token: 'super-secret-token',
    account: { botId: 'bot-42', accountId: 'bot-42' },
    connected: true,
    getStatus() {
      return { accountId: 'bot-42', connected: true, hasToken: true, dataDirectory: 'memory://' }
    },
  }
  const { api } = createApi({ service })
  const res = await call(api, { url: `${WEB_API_PREFIX}/status` })
  assert.equal(res.status, 200)
  assert.deepEqual(res.body, {
    bound: true,
    botId: 'bot-42',
    accountId: 'bot-42',
    connected: true,
    polling: true,
    lastError: null,
    // No bridge row is mounted in this fixture, so there is nothing to change
    // and nothing to report about the host surfaces it would have probed.
    settings: null,
    hostCompat: null,
    undelivered: null,
    catalog: null,
    permissions: null,
  })
  assert.ok(!res.raw.includes('super-secret-token'), 'bot_token must never reach the client')
})

test('GET /status falls back to the stored account when the service has not loaded it', async () => {
  const store = createMemoryStore({ accountId: 'stored-bot', botToken: 'stored-token', botId: 'stored-bot' })
  const service = {
    dataDirectory: 'memory://',
    connected: false,
    getStatus: () => ({ accountId: 'default', connected: false, hasToken: false }),
  }
  const { api } = createApi({ service, store })
  const res = await call(api, { url: `${WEB_API_PREFIX}/status` })
  assert.equal(res.body.bound, true)
  assert.equal(res.body.botId, 'stored-bot')
  assert.equal(res.body.accountId, 'stored-bot')
  assert.equal(res.body.polling, false)
  assert.ok(!res.raw.includes('stored-token'))
})

