test('POST /login/begin returns a QR, its rendered image URL, and the poll interval', async () => {
  const { api } = createApi({ service: undefined, intervalMs: 2500 })
  const res = await call(api, { method: 'POST', url: `${WEB_API_PREFIX}/login/begin` })
  assert.equal(res.status, 200)
  assert.equal(res.body.qrcode, 'qr-1')
  assert.match(res.body.qrUrl, /^https:\/\/liteapp\.weixin\.qq\.com\//)
  assert.equal(res.body.qrImageUrl, `${WEB_API_PREFIX}/qr.svg?qrcode=qr-1`)
  assert.equal(res.body.intervalMs, 2500)
  assert.ok(res.body.expiresAt > Date.now())

  const image = createRes()
  await api.handler(createReq({ url: `${WEB_API_PREFIX}/qr.svg?qrcode=qr-1` }), image)
  assert.equal(image.statusCode, 200)
  assert.match(image.headers['content-type'], /image\/svg\+xml/)
  assert.match(image.body, /^<svg /)
  assert.match(image.body, /#000000/)
})

test('POST /login/begin reports an upstream failure as 502 and records it', async () => {
  const { api } = createApi({ service: undefined, beginError: new Error('network down') })
  const res = await call(api, { method: 'POST', url: `${WEB_API_PREFIX}/login/begin` })
  assert.equal(res.status, 502)
  assert.equal(res.body.status, 'error')
  assert.match(res.body.message, /network down/)

  const status = await call(api, { url: `${WEB_API_PREFIX}/status` })
  assert.match(status.body.lastError, /network down/)
})

