/**
 * Minimal React with just the hooks the section uses, enough to render and
 * re-render against a stable hook store.
 *
 * @returns {{api: object, effects: object[], runEffects: () => Promise<void>, reset: () => void}}
 * the double.
 */
function createFakeReact() {
  const hooks = []
  const effects = []
  const cleanups = []
  let cursor = 0
  return {
    effects,
    reset() {
      cursor = 0
    },
    async runEffects() {
      const pending = effects.splice(0, effects.length)
      for (const entry of pending) {
        const result = entry.fn()
        if (result && typeof result.then === 'function') await result
        else if (typeof result === 'function') cleanups.push(result)
      }
      await settle()
    },
    /** Run every captured effect cleanup so no timer keeps the test process alive. */
    cleanupAll() {
      for (const fn of cleanups.splice(0, cleanups.length)) fn()
    },
    api: {
      createElement(type, props, ...children) {
        return { type, props: { ...(props ?? {}), children: children.length <= 1 ? children[0] : children } }
      },
      useState(initial) {
        const index = cursor++
        if (!(index in hooks)) hooks[index] = typeof initial === 'function' ? initial() : initial
        return [
          hooks[index],
          (next) => {
            hooks[index] = typeof next === 'function' ? next(hooks[index]) : next
          },
        ]
      },
      useEffect(fn) {
        effects.push({ fn })
        cursor += 1
      },
      useCallback(fn) {
        cursor += 1
        return fn
      },
      useMemo(fn) {
        cursor += 1
        return fn()
      },
      useRef(initial) {
        const index = cursor++
        if (!(index in hooks)) hooks[index] = { current: initial }
        return hooks[index]
      },
    },
  }
}

/**
 * Load the client module against a stub `window` and a stub `fetch`.
 *
 * @param {Function} [fetchImpl] - replacement fetch.
 * @returns {{source: string, spec: object, react: object}} the captured spec.
 */
function loadClient(fetchImpl) {
  const source = readFileSync(CLIENT_PATH, 'utf8')
  const react = createFakeReact()
  let spec
  const windowStub = {
    __ModuleLoader__: {
      load(candidate) {
        spec = candidate
      },
    },
  }
  const factory = new Function('window', 'fetch', 'setTimeout', 'clearTimeout', source)
  factory(
    windowStub,
    fetchImpl ?? (async () => {
      throw new Error('the client must not fetch during load/apply')
    }),
    setTimeout,
    clearTimeout,
  )
  assert.ok(spec, 'the client module must register itself with __ModuleLoader__')
  return { source, spec, react }
}

/**
 * Register the client module into the settings slot and return its component.
 *
 * @param {object} spec - client module spec from {@link loadClient}.
 * @param {object} react - fake React.
 * @returns {{component: Function, options: object, injected: string[]}} the registration.
 */
function mountSection(spec, react) {
  const registrations = []
  const injected = []
  spec.factory(() => react.api).apply({
    slots: {
      inject(key, callback) {
        injected.push(key)
        return callback()
      },
      register(options, component) {
        registrations.push({ options, component })
        return () => {}
      },
    },
  })
  assert.deepEqual(injected, ['settings.section'])
  assert.equal(registrations.length, 1)
  return { ...registrations[0], injected }
}

/**
 * Walk a rendered tree depth-first.
 *
 * @param {object} node - tree node.
 * @param {(node: object) => boolean} predicate - matcher.
 * @returns {object | undefined} the first match.
 */
function findNode(node, predicate) {
  if (node === null || typeof node !== 'object') return undefined
  if (Array.isArray(node)) {
    for (const child of node) {
      const found = findNode(child, predicate)
      if (found) return found
    }
    return undefined
  }
  if (predicate(node)) return node
  return findNode(node.props?.children, predicate)
}

/**
 * Collect every string child in a tree.
 *
 * @param {object} node - tree node.
 * @param {string[]} [into] - accumulator.
 * @returns {string[]} the strings.
 */
function collectStrings(node, into = []) {
  if (node === null || typeof node !== 'object') return into
  if (Array.isArray(node)) {
    for (const child of node) collectStrings(child, into)
    return into
  }
  if (typeof node.props?.children === 'string') into.push(node.props.children)
  collectStrings(node.props?.children, into)
  return into
}

/**
 * Remove block and line comments from JavaScript source.
 *
 * @param {string} source - source text.
 * @returns {string} the source with comments blanked out.
 */
function stripComments(source) {
  return source
    .replace(/\/\*[\s\S]*?\*\//g, ' ')
    .replace(/(^|[^:])\/\/[^\n]*/g, '$1')
}

test('client.js loads lazily, requires only react, and registers the settings section', () => {
  const { source, spec, react } = loadClient()
  assert.equal(spec.id, 'wechat-feishu-linker')
  assert.equal(typeof spec.factory, 'function')

  // No Harness client package may be imported, and no DOM may be touched outside
  // the component subtree. Comments are stripped first so the header prose that
  // *documents* those rules cannot trip the check.
  const code = stripComments(source)
  assert.ok(!/require\(\s*['"]@deepseek-ai/.test(code), 'no @deepseek-ai require')
  assert.ok(!/from\s+['"]@deepseek-ai/.test(code), 'no @deepseek-ai import')
  assert.ok(!/\bdocument\b/.test(code), 'the client must not touch document directly')

  const mod = spec.factory((name) => {
    assert.equal(name, 'react')
    return react.api
  })
  assert.deepEqual(mod.inject, ['slots'])
  assert.equal(typeof mod.apply, 'function')

  const registration = mountSection(spec, react)
  assert.equal(registration.options.name, 'settings.section')
  assert.equal(registration.options.id, 'wechat-ilink')
  assert.equal(typeof registration.options.order, 'number')
  // The section now covers both channels, so its label names the bot rather
  // than WeChat alone — the two channel cards inside say which is which.
  assert.equal(registration.options.label, 'ClawBot 设置')
})

test('the settings section renders a theme-token-only, self-contained tree', () => {
  const { spec, react } = loadClient()
  const { component } = mountSection(spec, react)

  react.reset()
  const tree = component({ close: () => {} })

  assert.equal(tree.type, 'div')
  assert.equal(tree.props.className, 'wil_root')

  const style = findNode(tree, (node) => node.type === 'style')
  assert.ok(style, 'the section renders its own stylesheet inside its subtree')
  const css = style.props.children
  assert.match(css, /--dsw-alias-/)
  assert.ok(!/#[0-9a-fA-F]{3,8}\b/.test(css), 'no literal hex colours in the stylesheet')
  assert.ok(!/\brgba?\(/.test(css), 'no literal rgb()/rgba() colours')
  assert.ok(!/\bhsla?\(/.test(css), 'no literal hsl() colours')

  const labels = collectStrings(tree)
  assert.ok(labels.includes('微信'), 'the WeChat card names its channel')
  assert.ok(labels.includes('飞书'), 'and so does the Feishu card')
  assert.ok(labels.includes('加载中'), 'the initial state is visible before any fetch resolves')
  assert.ok(labels.includes('扫码绑定'), 'the bind affordance is reachable')
  assert.ok(labels.some((label) => label.includes('正在加载')), 'the workspace panel degrades while loading')
})

test('the settings section reports a host without a Web service', async () => {
  const { spec, react } = loadClient()
  const { component } = mountSection(spec, react)

  react.reset()
  component({})
  await react.runEffects()

  react.reset()
  const tree = component({})
  const labels = collectStrings(tree)
  assert.ok(
    labels.some((label) => label.includes('当前宿主未启用 Web 服务')),
    `expected the degraded host message, got: ${labels.join(' | ')}`,
  )
})

test('the settings section binds, shows the QR, and polls to success', async () => {
  const requests = []
  let bound = false
  const fetchImpl = async (url, init) => {
    requests.push({ url, method: init?.method ?? 'GET' })
    if (url.endsWith('/login/begin')) {
      return {
        ok: true,
        status: 200,
        json: async () => ({
          qrcode: 'qr-live',
          qrUrl: 'https://liteapp.weixin.qq.com/q/live',
          qrImageUrl: '/wechat-ilink/api/qr.svg?qrcode=qr-live',
          expiresAt: Date.now() + 60000,
          intervalMs: 5,
        }),
      }
    }
    if (url.includes('/login/poll')) {
      bound = true
      return { ok: true, status: 200, json: async () => ({ status: 'success', botId: 'bot-live' }) }
    }
    if (url.endsWith('/status')) {
      return {
        ok: true,
        status: 200,
        json: async () => ({
          bound,
          botId: bound ? 'bot-live' : '',
          accountId: bound ? 'bot-live' : 'default',
          connected: bound,
          polling: bound,
          lastError: null,
        }),
      }
    }
    return { ok: true, status: 200, json: async () => ({ available: false, items: [] }) }
  }

  const { spec, react } = loadClient(fetchImpl)
  const { component } = mountSection(spec, react)

  try {
    react.reset()
    component({})
    await react.runEffects()
    react.reset()
    let tree = component({})

    const bindButton = findNode(tree, (node) => node.type === 'button' && collectStrings(node).includes('扫码绑定'))
    assert.ok(bindButton, 'the bind button is rendered for an unbound channel')

    bindButton.props.onClick()
    await settle()
    react.reset()
    tree = component({})

    const image = findNode(tree, (node) => node.type === 'img')
    assert.ok(image, 'the QR image appears after /login/begin')
    assert.equal(image.props.src, '/wechat-ilink/api/qr.svg?qrcode=qr-live')
    assert.ok(requests.some((entry) => entry.url.endsWith('/login/begin') && entry.method === 'POST'))

    // Arm the poll loop, then let its timer fire: the mocked endpoint answers
    // `success` on the first poll.
    await react.runEffects()
    await new Promise((resolve) => setTimeout(resolve, 40))
    react.reset()
    tree = component({})
    const labels = collectStrings(tree)
    assert.ok(labels.includes('绑定成功'), `expected the success phase, got: ${labels.join(' | ')}`)
    assert.ok(requests.some((entry) => entry.url.includes('/login/poll?qrcode=qr-live')))
  } finally {
    react.cleanupAll()
  }
})

// ─────────────────────────── runtime settings routes ───────────────────────────

/**
 * A bridge settings handle double that keeps one value, like the real one.
 *
 * @param {object} [initial] - starting settings.
 * @returns {object} `{ read, write, writes }`.
 */
function createSettingsHandle(initial = { displayMode: 'compact', typingIndicator: true }) {
  let current = { ...initial }
  const writes = []
  return {
    writes,
    read: () => ({ ...current }),
    write: async (patch) => {
      writes.push(patch)
      if (patch.displayMode !== undefined && patch.displayMode !== 'compact' && patch.displayMode !== 'quiet') {
        return { ok: false, message: 'displayMode 只能是 compact 或 quiet' }
      }
      current = { ...current, ...patch }
      return { ok: true, settings: { ...current }, persisted: true }
    },
  }
}

test('GET /status carries the live settings so the page can render them', async () => {
  const handle = createSettingsHandle({ displayMode: 'quiet', typingIndicator: false })
  const { api } = createApi({ getBridgeSettings: () => handle })
  const res = await call(api, { url: `${WEB_API_PREFIX}/status` })
  assert.equal(res.status, 200)
  assert.deepEqual(res.body.settings, { displayMode: 'quiet', typingIndicator: false })
})

test('POST /settings writes through the bridge and answers with what it now holds', async () => {
  const handle = createSettingsHandle()
  const { api } = createApi({ getBridgeSettings: () => handle })
  const res = await call(api, {
    url: `${WEB_API_PREFIX}/settings`,
    method: 'POST',
    body: JSON.stringify({ displayMode: 'quiet' }),
  })
  assert.equal(res.status, 200)
  assert.deepEqual(res.body, {
    ok: true,
    settings: { displayMode: 'quiet', typingIndicator: true },
    persisted: true,
  })
  assert.deepEqual(handle.writes, [{ displayMode: 'quiet' }])
})

test('POST /settings rejects a value the bridge does not implement', async () => {
  const handle = createSettingsHandle()
  const { api } = createApi({ getBridgeSettings: () => handle })
  const res = await call(api, {
    url: `${WEB_API_PREFIX}/settings`,
    method: 'POST',
    body: JSON.stringify({ displayMode: 'full' }),
  })
  assert.equal(res.status, 400)
  assert.equal(res.body.ok, false)
  assert.match(res.body.message, /displayMode/)
})

test('POST /settings says so when the bridge row is not running', async () => {
  // `settings: null` in `/status` and this response are how the page knows to
  // explain itself instead of offering a control that cannot do anything.
  const { api } = createApi({ getBridgeSettings: () => undefined })
  const res = await call(api, {
    url: `${WEB_API_PREFIX}/settings`,
    method: 'POST',
    body: JSON.stringify({ displayMode: 'quiet' }),
  })
  assert.equal(res.status, 200)
  assert.equal(res.body.ok, false)
  assert.equal(res.body.available, false)
  assert.match(res.body.message, /桥接未运行/)
})

// ──────────────────────────── Feishu channel routes ────────────────────────────

/**
 * A Feishu service double, shaped like `FeishuChannel`.
 *
 * @param {object} [over] - overrides.
 * @returns {object} the double.
 */
function createFeishuService(over = {}) {
  return {
    getStatus: () => ({
      channel: 'feishu',
      bound: false,
      appId: '',
      connected: false,
      connectionState: 'unbound',
      ...(over.status ?? {}),
    }),
    beginLogin:
      over.beginLogin ??
      (async () => ({
        deviceCode: 'dc-1',
        qrUrl: 'https://open.feishu.cn/page/launcher?user_code=ABCD-1234&from=sdk',
        userCode: 'ABCD-1234',
        interval: 5000,
        expiresAt: Date.now() + 600_000,
      })),
    pollLogin: over.pollLogin ?? (async () => ({ status: 'pending', interval: 5000 })),
    bind: over.bind ?? (async () => ({ ok: true })),
    logout: over.logout ?? (async () => {}),
  }
}

test('GET /feishu/status distinguishes a missing row from an unbound one', async () => {
  // "The plugin row is not loaded" and "no credentials yet" look identical from
  // the outside, and only one of them is fixed by typing something.
  const missing = createApi({ feishuService: undefined })
  const absent = await call(missing.api, { url: `${WEB_API_PREFIX}/feishu/status` })
  assert.equal(absent.status, 200)
  assert.equal(absent.body.mounted, false)

  const present = createApi({ feishuService: createFeishuService() })
  const there = await call(present.api, { url: `${WEB_API_PREFIX}/feishu/status` })
  assert.equal(there.body.mounted, true)
  assert.equal(there.body.status.connectionState, 'unbound')
})

test('[REGRESSION] the QR the registration returns is actually servable as an image', async () => {
  // The card renders this URL straight into an <img>. A URL the image route does
  // not recognise is a broken image in the UI and nothing else — no error, no
  // log, just a QR that never appears.
  const { api } = createApi({ feishuService: createFeishuService() })

  const begun = await call(api, { url: `${WEB_API_PREFIX}/feishu/login/begin`, method: 'POST', body: '{}' })
  assert.equal(begun.status, 200)
  assert.equal(begun.body.ok, true)
  assert.equal(begun.body.qrcode, 'dc-1')
  assert.match(begun.body.qrImageUrl, /\/feishu\/qr\.svg\?qrcode=dc-1$/)

  const imagePath = begun.body.qrImageUrl.slice(begun.body.qrImageUrl.indexOf(WEB_API_PREFIX))
  const image = await call(api, { url: imagePath })
  assert.equal(image.status, 200, `the image route must serve ${imagePath}`)
  assert.match(image.headers['content-type'], /image\/svg\+xml/)
  assert.match(image.raw, /^<svg/u)
  assert.ok(image.raw.length > 500, 'a real QR, not an empty frame')
})

test('the image route refuses a code this process never issued', async () => {
  // The URL is read from the server's own record, so a request can never have an
  // arbitrary URL rendered as a QR and handed back to the browser.
  const { api } = createApi({ feishuService: createFeishuService() })
  const res = await call(api, { url: `${WEB_API_PREFIX}/feishu/qr.svg?qrcode=not-mine` })
  assert.equal(res.status, 404)
})

